"use strict";(globalThis.webpackChunkllm_d_website=globalThis.webpackChunkllm_d_website||[]).push([[6021],{43129(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>s,default:()=>h,frontMatter:()=>o,metadata:()=>i,toc:()=>d});var i=t(1707),a=t(74848),r=t(28453);const o={title:"llm-d v0.7: From Feature Introduction to Production Hardening",description:"llm-d v0.7 shifts focus from proving capabilities to making them deployable, with changes across deployment tooling, hardware support, documentation, and continuous integration.",slug:"llm-d-v0.7-from-feature-introduction-to-production-hardening",authors:["llm-d-maintainers"],tags:["releases","announce","llm-d"]},s="llm-d v0.7: From Feature Introduction to Production Hardening",l={authorsImageUrls:[void 0]},d=[{value:"Operator Experience: Standalone Mode and Kustomize-First",id:"operator-experience-standalone-mode-and-kustomize-first",level:2},{value:"Documentation Built from Scratch",id:"documentation-built-from-scratch",level:2},{value:"Broadening Hardware and Disaggregation Reach",id:"broadening-hardware-and-disaggregation-reach",level:2},{value:"Workload-Aware Orchestration",id:"workload-aware-orchestration",level:2},{value:"Multi-Tier KV Caching and Intelligent Routing",id:"multi-tier-kv-caching-and-intelligent-routing",level:2},{value:"CI That Tests What You Actually Deploy",id:"ci-that-tests-what-you-actually-deploy",level:2},{value:"What This Means for Your Evaluation",id:"what-this-means-for-your-evaluation",level:2},{value:"What Is Next?",id:"what-is-next",level:2},{value:"Community and Contribution",id:"community-and-contribution",level:2}];function c(e){const n={a:"a",code:"code",h2:"h2",li:"li",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.p,{children:"If v0.6 was about proving what llm-d could do\u2014OTel integration, prefill/decode disaggregation, initial multi-accelerator images\u2014then v0.7 is about making sure you can actually deploy it. The theme across every category is the same: remove friction, broaden hardware reach, and give operators the documentation and CI coverage to trust the system in production."}),"\n",(0,a.jsxs)(n.p,{children:["Recent external validations demonstrated llm-d's ",(0,a.jsx)(n.a,{href:"https://github.com/llm-d/llm-d#performance-highlights",children:"performance gains"}),". Those capabilities remain and continue to improve, but v0.7's investment is making them accessible: onboarding guides, tested installation paths, and confidence the guides work on your target platform."]}),"\n",(0,a.jsx)(n.h2,{id:"operator-experience-standalone-mode-and-kustomize-first",children:"Operator Experience: Standalone Mode and Kustomize-First"}),"\n",(0,a.jsx)(n.p,{children:"A recurring feedback from platform teams evaluating llm-d was that initial deployments involved too many moving parts. In v0.7, we have fundamentally simplified the day-one experience."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Standalone Mode Default"}),": The default deployment now runs in standalone mode using a generic proxy (Envoy), rather than requiring the full Gateway API Inference Extension (GAIE) stack. You can go from clone to serving in minutes, and layer on gateway features as your deployment matures. While the full GAIE power remains available\u2014GAIE has been updated to v1.5.0, Istio to 1.29.2, and AgentGateway to v1.1.0\u2014it is no longer the first thing you encounter. This responds directly to feedback that initial setup had too many moving parts."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"llm-d Router"}),": With standalone mode broadening how llm-d deploys, we are renaming the core component to the ",(0,a.jsx)(n.strong,{children:"llm-d Router"}),' \u2014 the functional combination of a Proxy and an Endpoint Picker (EPP). This replaces the previous "inference scheduler" and "inference gateway" terminology, which conflicted with Kubernetes scheduling concepts and was too narrowly tied to the Gateway API. The repository has been renamed to ',(0,a.jsx)(n.a,{href:"https://github.com/llm-d/llm-d-router",children:(0,a.jsx)(n.code,{children:"llm-d-router"})}),"."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Kustomize Migration"}),": The entire installation surface has been migrated from Helm and Helmfile to Kustomize. Every deployment guide\u2014optimized baseline, prefix-cache-aware routing, prefill/decode disaggregation, workload-variant autoscaling, Intel XPU deployment\u2014now uses Kustomize bases with per-platform overlays for GKE, OpenShift, and other Kubernetes distributions. The previous llm-d-infra and llm-d-modelservice Helm charts are deprecated, and the monolithic Helmfile CI workflow has been replaced with ",(0,a.jsx)(n.code,{children:"ci-kustomize-dry-run.yaml"}),"."]}),"\n",(0,a.jsx)(n.p,{children:"The technical reasoning is pragmatic: Kustomize overlays compose more naturally than Helm value files when patching platform-specific details like node selectors, storage classes, or NCCL tuner configurations without maintaining separate charts. For teams already managing Kubernetes resources with GitOps tools like ArgoCD or Flux, this eliminates a tooling boundary and makes llm-d configurations first-class citizens in existing deployment pipelines."}),"\n",(0,a.jsx)(n.h2,{id:"documentation-built-from-scratch",children:"Documentation Built from Scratch"}),"\n",(0,a.jsx)(n.p,{children:'The documentation overhaul is the largest single category in this release by volume, with v0.7 introducing over 10,000 lines of new documentation content. To ensure teams can onboard without tribal knowledge, the entire guide taxonomy was restructured for clarity: what was called "inference-scheduling" became "optimized-baseline" to better reflect what it delivers. New guides for batch gateway, flow control, and predicted latency routing fill gaps that previously required reading source code.'}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Architecture Reference"}),": Full coverage of EPP design (scheduling, flow control, request handling), KV management subsystems (KV Indexer, KV Offloader, routing plugin integration), disaggregation operations (KV cache transfer, NIXL library, routing sidecar coordination), autoscaling mechanics, and the latency predictor. A new API reference section documents EPP HTTP headers, EndpointPickerConfig, InferenceModelRewrite, InferenceObjective, and InferencePool resources with concrete examples."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Visual Topology"}),": New diagrams make system architecture legible at a glance. Each major subsystem\u2014KV cache indexing, prefill/decode coordination, multi-tier offloading\u2014has visual representations showing component interaction and data flow, providing the conceptual grounding operators need to reason about performance and troubleshoot issues."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Operational Tooling"}),": Interactive tuning scripts for flow control let operators explore parameter spaces without editing YAML by hand. A new health check script validates deployments end-to-end, catching configuration errors before they surface in production. The autoscaling documentation received a five-part series covering fundamentals, HPA/KEDA design choices, Workload Variant Autoscaler deep-dive, native HPA patterns, and guide alignment\u2014clarifying when WVA's variant-aware logic provides value over simpler approaches."]}),"\n",(0,a.jsx)(n.h2,{id:"broadening-hardware-and-disaggregation-reach",children:"Broadening Hardware and Disaggregation Reach"}),"\n",(0,a.jsx)(n.p,{children:"v0.7 expands our footprint as a hardware-agnostic control plane, readying the stack for the next generation of accelerators."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"CUDA 13 and Blackwell Support"}),": We have updated from CUDA 12.9.1 to 13.0.2\u2014a breaking change requiring NVIDIA driver 580 or later. This unlocks first-class support for Blackwell-generation hardware, including a dedicated ",(0,a.jsx)(n.code,{children:"llm-d-cuda-gb200"})," Docker image with GB200-specific DeepEP wheels and NVSHMEM support. The ",(0,a.jsx)(n.code,{children:"TORCH_CUDA_ARCH_LIST"})," now natively includes sm100 targets. The core inference stack has also been updated, bringing vLLM to 0.19.1 (now tracking the neuralmagic fork with targeted NaN-fix cherry-picks), LMCache to v0.4.4, and FlashInfer to v0.6.6. Build infrastructure improvements include sccache in the runtime stage and ",(0,a.jsx)(n.code,{children:"MAX_JOBS=3"})," as default to prevent out-of-memory failures during source builds."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Expanded Ecosystem"}),": We have added Rebellions as a supported accelerator vendor, shipped an AMD ROCm deployment guide, and enabled Tensor Parallelism (TP=2) for Qwen3-32B on Intel XPUs. TPU support now spans v6e and v7 with consistent configurations across generations, including a new RunAI model streamer integration. HPU and CPU images have been updated."]}),"\n",(0,a.jsx)(n.p,{children:"If you are evaluating llm-d against a mixed-accelerator fleet\u2014combining NVIDIA GPUs with AMD MI-series, Intel XPUs, Google TPUs, or Rebellions ATOM chips\u2014v0.7 is the first release where every supported platform ships with tested images, validated guides, and production-grade documentation."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Prefill/Decode (P/D) Disaggregation"}),": Prefill/decode disaggregation\u2014where prefill computation (token-in, compute-bound) runs on separate pods from decode (token-out, memory-bandwidth-bound)\u2014enables higher throughput by allowing independent scaling of each phase and eliminating prefill interference with decode latency. Version 0.7 extends P/D support to Google TPU v7 with a complete guide for Qwen 3.5, adds an Oracle Cloud Infrastructure deployment path, and ships a comprehensive three-part disaggregation architecture series explaining how KV cache transfer works, what NIXL (NVIDIA Inference Xfer Library) provides, and how the routing sidecar coordinates transfer between prefill and decode instances. The guide has been rewritten with Kustomize and now includes per-platform overlays for NVIDIA GPUs (vLLM and SGLang), Google TPUs, and Oracle Cloud Infrastructure with platform-specific tuning isolated in overlay patches."]}),"\n",(0,a.jsx)(n.h2,{id:"workload-aware-orchestration",children:"Workload-Aware Orchestration"}),"\n",(0,a.jsx)(n.p,{children:"Intelligence is increasingly moving from the infrastructure layer into workload characteristics. v0.7 introduces two major experimental features to handle complex multi-tenant environments:"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Flow Control"}),": We have introduced centralized request queuing and admission control at the Router level. Traditional load balancing treats all requests identically and commits them immediately to backend queues. This breaks down for LLM inference where resource consumption varies wildly per request\u2014a 32K-token prefill followed by minimal decode consumes radically different resources than a balanced workload\u2014and where multi-tenant environments require fairness guarantees."]}),"\n",(0,a.jsx)(n.p,{children:'Flow Control moves request queuing to the llm-d Router, enabling intelligent admission control before requests reach model servers. Incoming requests are classified by a FlowKey combining Fairness ID and Priority. The Endpoint Picker (EPP) maintains separate in-memory queues for each flow and dispatches based on three criteria: priority (service highest-priority bands first), fairness (cycle through tenants within a band), and ordering (maintain request sequence within a flow). This architecture prevents noisy neighbors from starving other tenants, enables "no-regret scheduling" that holds requests during saturation rather than committing them to stuck local queues, and integrates with InferenceObjective resources for dynamic SLO enforcement. The feature ships with defaults explicitly designed to mimic legacy first-come-first-served behavior, ensuring seamless transition for existing workloads.'}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Batch Gateway"}),": An OpenAI-compatible Batch API designed for large-scale batch inference. Production LLM deployments rarely serve only interactive traffic. Batch workloads\u2014large-scale embedding generation, synthetic data creation, offline document processing\u2014represent significant compute demand but have fundamentally different latency tolerance and scheduling requirements than chat or completion endpoints."]}),"\n",(0,a.jsxs)(n.p,{children:["The new Batch Gateway provides an OpenAI-compatible ",(0,a.jsx)(n.code,{children:"/v1/batches"})," and ",(0,a.jsx)(n.code,{children:"/v1/files"})," API for submitting and tracking batch jobs containing up to 50,000 requests. The architecture separates batch from interactive traffic while enabling both to coexist on shared infrastructure through integration with flow control backpressure mechanisms. Three components handle the batch lifecycle: API Server (REST endpoints for job submission, management, file handling), Batch Processor (pulls jobs from a priority queue, builds per-model execution plans, dispatches to llm-d Router, writes results to output files), and Garbage Collector (cleans up expired jobs and files based on configurable retention policies). Storage is pluggable across layers: PostgreSQL or Redis/Valkey for metadata, Redis/Valkey for queue and event streams, and S3 or filesystem for input and output files."]}),"\n",(0,a.jsx)(n.p,{children:"Both Flow Control and Batch Gateway ship as experimental features, reflecting their operational complexity and the need for real-world validation before stabilization."}),"\n",(0,a.jsx)(n.h2,{id:"multi-tier-kv-caching-and-intelligent-routing",children:"Multi-Tier KV Caching and Intelligent Routing"}),"\n",(0,a.jsx)(n.p,{children:"Managing KV-cache pressure effectively dictates whether a system can sustain low tail-latency under load. Version 0.7 significantly expands KV cache management capabilities across three dimensions: more intelligent routing, multi-tier storage, and comprehensive architectural documentation."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Tiered Prefix Cache Storage"}),": Building on our storage architectures, v0.7 introduces an AWS EFS backend, formalizing multi-tier KV cache offloading from GPU HBM to CPU DRAM to persistent storage (local NVMe or network-attached storage like AWS EFS). This enables handling longer contexts than would fit in GPU memory alone, trading storage I/O latency for the ability to preserve and reuse expensive prefill computation. The tiered storage architecture integrates with vLLM's OffloadingConnector, making the optimization transparent to model servers while the router manages tier placement and retrieval."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Precise Prefix Cache-Aware Routing"}),": Real-time prefix cache tracking is now enabled by default, replacing hashSeed-based workarounds with precise tracking. The precise-prefix-cache-aware guide now enables speculative indexing by default, removing hashSeed and PYTHONHASHSEED workarounds that previously limited cache effectiveness. The router tracks cache state in real-time across the fleet, scoring candidate endpoints based on prefix overlap and routing to pods most likely to have relevant blocks already resident in GPU memory. This routing intelligence has been validated across platforms\u2014passing nightly tests on both Container Kubernetes Service and OpenShift\u2014and now extends to Intel XPU deployments where TP=2 configurations for Qwen3-32B are fully supported and tested."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Predicted Latency-Based Scheduling"}),": We have completely rewritten the predicted latency architecture with a new production-ready guide. The architecture documentation explains how the latency predictor provides routing intelligence, allowing the system to natively route requests based on latency predictions rather than basic heuristics."]}),"\n",(0,a.jsx)(n.p,{children:"New documentation sections explain the KV cache management subsystem in depth: how the KV Indexer maintains a distributed index of block locations across pods, how the KV Offloader coordinates tier transitions, and how routing plugins consume this state to make cache-aware placement decisions."}),"\n",(0,a.jsx)(n.h2,{id:"ci-that-tests-what-you-actually-deploy",children:"CI That Tests What You Actually Deploy"}),"\n",(0,a.jsx)(n.p,{children:"The operational rigor of a system is only as good as its CI pipeline. We have entirely rewritten our testing infrastructure, moving away from monolithic accelerator scripts (550-600 lines each) to focused, per-guide nightly test matrices."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Multi-Platform Validation"}),": New nightly jobs cover optimized baseline, precise prefix cache, predicted latency, and tiered prefix cache with CPU offloading, each parameterized across CKS, GKE, and OpenShift. This ensures guides work on the platforms they claim to support."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Real Optimization Assertions"}),": The predicted latency validation workflow exemplifies the new rigor. Our predicted latency validation scrapes EPP ",(0,a.jsx)(n.code,{children:"/metrics"})," endpoints to verify the predictor served real predictions instead of falling back to heuristics. This is not smoke testing; it asserts that the optimization path you configured is actually running."]}),"\n",(0,a.jsxs)(n.p,{children:["Additional CI improvements include an image verification workflow, a ",(0,a.jsx)(n.code,{children:"/test-nightly"})," slash command with glob patterns enabling fork contributors to trigger targeted nightly runs, and a badge matrix generator keeping the README status table synchronized with actual test results. Nightly results now post status comments directly on pull requests, surfacing failures immediately rather than requiring manual log inspection."]}),"\n",(0,a.jsx)(n.p,{children:"Across 63 changed workflow files, the net delta is actually 2,785 fewer lines of YAML\u2014consolidation rather than expansion\u2014while covering substantially more of the deployment surface."}),"\n",(0,a.jsx)(n.h2,{id:"what-this-means-for-your-evaluation",children:"What This Means for Your Evaluation"}),"\n",(0,a.jsx)(n.p,{children:"If you evaluated llm-d previously and concluded it was not ready for production use, v0.7 merits a second look. The deployment path is simpler through standalone mode and Kustomize-native installation. Hardware coverage spans Blackwell GPUs, AMD ROCm, Intel XPUs, Google TPUs, Rebellions ATOM, and CPU deployments. Documentation is comprehensive enough to onboard a team without requiring tribal knowledge or source code archaeology. The CI matrix covers enough deployment surface to provide confidence that guides actually work on the platforms they claim to support."}),"\n",(0,a.jsx)(n.p,{children:"This release represents a 3.5\xd7 increase in pull request volume over v0.6. The project is accelerating, and the v0.7 investment in foundations\u2014documentation, testing, installation simplification\u2014is the kind of work that compounds in value as the project scales."}),"\n",(0,a.jsx)(n.h2,{id:"what-is-next",children:"What Is Next?"}),"\n",(0,a.jsxs)(n.p,{children:["The project is accelerating, and the foundational investments made in v0.7 set the stage for upcoming milestones. The ",(0,a.jsx)(n.a,{href:"https://github.com/llm-d/llm-d/issues/1520",children:"v0.8 release milestone"})," focuses on production readiness, reinforcement learning workloads, and expanded accelerator coverage."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Production graduation"}),": Flow Control and Batch Gateway move from experimental to production-ready. Flow Control receives guide documentation for multi-tenant deployments, while Batch Gateway undergoes hardening with enterprise storage backends and at-scale validation. Multi-modal serving\u2014image+text models like LLaVA and Qwen-VL\u2014gains production guides and end-to-end testing."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Reinforcement learning infrastructure"}),": Initial RL support lands through Python scheduler integration with the Endpoint Picker, enabling gym-style RL training loops to directly influence routing decisions. Non-Kubernetes deployment mode enables llm-d in Slurm clusters and research labs through file-based service discovery. GPU time-slicing platform support allows multiple RL rollout workers to share accelerators during policy evaluation phases."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Advanced disaggregation"}),": NIXL (NVIDIA Inference Xfer Library) receives TTL-based cache eviction and request draining for graceful pod termination. KV transfer connectors expand beyond NVIDIA with Mooncake (Alibaba) and MoRI (Microsoft) integrations. GB200 NVL72 configurations gain dedicated guides. Multi-tier storage offloading extends to object storage backends alongside the existing filesystem tier."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"CI and operational rigor"}),": Nightly tests expand to TPU and AMD ROCm platforms. Each guide receives automated lm-eval and performance benchmarking in CI. The release process itself gets documented, and CI jobs migrate to nightly-built images rather than on-demand builds. Monitoring setup becomes streamlined with consolidated dashboards and alerting configurations across guides."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Deployment flexibility"}),": Multi-model serving guides demonstrate running different models on shared hardware with LoRA adapter scheduling. Rollout guides cover blue/green deployments and version management for zero-downtime updates. Gateway installation prerequisites consolidate into a single reference, and request draining configurations become standard across all guides."]}),"\n",(0,a.jsxs)(n.p,{children:["We invite the community to explore the new capabilities and deploy the new well-lit paths. The full release notes and changelog are available on ",(0,a.jsx)(n.a,{href:"https://github.com/llm-d/llm-d/releases/tag/v0.7.0",children:"GitHub"}),"."]}),"\n",(0,a.jsx)(n.h2,{id:"community-and-contribution",children:"Community and Contribution"}),"\n",(0,a.jsx)(n.p,{children:"The llm-d community continues to expand: 23 new contributors in this release alone, with hardware vendor contributions from Rebellions, Intel, and AMD alongside ecosystem partners and individual developers. The project's velocity reflects both technical momentum and broadening adoption."}),"\n",(0,a.jsx)(n.p,{children:"To get started with llm-d v0.7:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Documentation"}),": ",(0,a.jsx)(n.a,{href:"https://llm-d.ai",children:"llm-d.ai"})]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Guides"}),": ",(0,a.jsx)(n.a,{href:"https://github.com/llm-d/llm-d/tree/main/docs/well-lit-paths",children:"Well-lit paths"})," for optimized baseline, prefix-cache routing, P/D disaggregation, and more"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Release notes"}),": ",(0,a.jsx)(n.a,{href:"https://github.com/llm-d/llm-d/releases/tag/v0.7.0",children:"v0.7.0 on GitHub"})]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Slack community"}),": Join the conversation at ",(0,a.jsx)(n.a,{href:"https://llm-d.ai/slack",children:"llm-d.ai/slack"})]}),"\n"]}),"\n",(0,a.jsxs)(n.p,{children:["Follow ",(0,a.jsx)(n.a,{href:"https://twitter.com/llm_d",children:"@llm_d"})," on Twitter for updates, or check ",(0,a.jsx)(n.a,{href:"https://llm-d.ai/community/events",children:"llm-d.ai/community/events"})," for upcoming community events. Come build with us."]})]})}function h(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},28453(e,n,t){t.d(n,{R:()=>o,x:()=>s});var i=t(96540);const a={},r=i.createContext(a);function o(e){const n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),i.createElement(r.Provider,{value:n},e.children)}},1707(e){e.exports=JSON.parse('{"permalink":"/llm-d.github.io/blog/llm-d-v0.7-from-feature-introduction-to-production-hardening","editUrl":"https://github.com/llm-d/llm-d/edit/main/website/blog/2026-05-12_llm-d-v0.7-from-feature-introduction-to-production-hardening.mdx","source":"@site/blog/2026-05-12_llm-d-v0.7-from-feature-introduction-to-production-hardening.mdx","title":"llm-d v0.7: From Feature Introduction to Production Hardening","description":"llm-d v0.7 shifts focus from proving capabilities to making them deployable, with changes across deployment tooling, hardware support, documentation, and continuous integration.","date":"2026-05-12T00:00:00.000Z","tags":[{"inline":false,"label":"Releases","permalink":"/llm-d.github.io/blog/tags/releases","description":"llm-d release announcements"},{"inline":false,"label":"Announcements","permalink":"/llm-d.github.io/blog/tags/announce","description":"Announcements that aren\'t news releases"},{"inline":false,"label":"llm-d release news","permalink":"/llm-d.github.io/blog/tags/llm-d","description":"llm-d tag description"}],"readingTime":13.19,"hasTruncateMarker":true,"authors":[{"name":"llm-d maintainers","url":"https://github.com/llm-d/llm-d/blob/main/MAINTAINERS.md","imageURL":"/llm-d.github.io/img/authors/llm-d-maintainers.png","key":"llm-d-maintainers","page":null}],"frontMatter":{"title":"llm-d v0.7: From Feature Introduction to Production Hardening","description":"llm-d v0.7 shifts focus from proving capabilities to making them deployable, with changes across deployment tooling, hardware support, documentation, and continuous integration.","slug":"llm-d-v0.7-from-feature-introduction-to-production-hardening","authors":["llm-d-maintainers"],"tags":["releases","announce","llm-d"]},"unlisted":false,"prevItem":{"title":"No Kubernetes? No Problem: llm-d Now Runs Anywhere","permalink":"/llm-d.github.io/blog/running-llm-d-without-kubernetes"},"nextItem":{"title":"Production-Grade LLM Inference at Scale with KServe, llm-d, and vLLM","permalink":"/llm-d.github.io/blog/production-grade-llm-inference-at-scale-kserve-llm-d-vllm"}}')}}]);